// Fix 1: Disable conflicting GCC attributes for C++ build
/*
#ifdef __cplusplus
    #undef UNUSED
    #undef NORET
    #undef PRINTF
    #undef SCANF
    #undef WUNRES
    #undef MALLOC
    #undef NONNULL
    #undef PURE
    #undef INLINE
    #undef likely
    #undef unlikely

    #define UNUSED
    #define NORET
    #define PRINTF(f,a)
    #define SCANF(f,a)
    #define WUNRES
    #define MALLOC
    #define NONNULL(...)
    #define PURE
    #define INLINE inline
    #define likely(x) (x)
    #define unlikely(x) (x)
#endif*/

// Fix C++ keywords
#define operator op_func
#define this     curr_conn

// Suppress warnings
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wdeprecated-declarations"
#pragma GCC diagnostic ignored "-Wwrite-strings"
#pragma GCC diagnostic ignored "-Wmissing-field-initializers"
#pragma GCC diagnostic ignored "-Wformat-security"
#pragma GCC diagnostic ignored "-fpermissive"


