cachetgcrt_exist_cb(cache_iter_t it)
{
	return kh_exist(certmap_tgcrt, it);
}

static void
cachetgcrt_del_cb(cache_iter_t it)
{
	kh_del(cstrmap_t, certmap_tgcrt, it);
}

static cache_iter_t
cachetgcrt_get_cb(cache_key_t key)
{
	return kh_get(cstrmap_t, certmap_tgcrt, key);
}

